//
// This is only a SKELETON file for the 'Forth' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const NUMBER = /^-?\d+$/;

export class Forth {
  constructor() {
    this._stack = [];
    this._words = {};
  }

  get stack() {
    return this._stack;
  }

  evaluate(input) {
    const tokens = input.trim().split(/\s+/).filter((t) => t.length > 0);

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];

      if (NUMBER.test(token)) {
        this._stack.push(parseInt(token, 10));
      } else if (token === ':') {
        const end = tokens.indexOf(';', i + 1);
        if (end === -1) {
          throw new Error('Invalid definition');
        }
        const name = tokens[i + 1];
        if (NUMBER.test(name)) {
          throw new Error('Invalid definition');
        }
        this._words[name.toLowerCase()] = tokens
          .slice(i + 2, end)
          .map((t) => t.toLowerCase());
        i = end;
      } else {
        const body = this._words[token.toLowerCase()];
        if (body) {
          for (const t of body) {
            this._exec(t);
          }
        } else {
